import numpy as np
from itertools import combinations_with_replacement
o=run(X)
def feats(cols):
    F=[X[:,c] for c in cols]
    F+= [(X[:,i]*X[:,j])[:,None] for i,j in combinations_with_replacement(cols,2)]
    F.append(np.ones((8000,1)))
    return np.hstack(F)
for cols in [[0],[1],[2],[3],[0,1],[0,1,2],[0,2],[2,3],[0,3],[0,1,2,3]]:
    F=feats(cols); 
    r2=[]
    for j in range(4):
        coef,_,_,_=np.linalg.lstsq(F,o[:,j],rcond=None); pred=F@coef
        r2.append(1-((o[:,j]-pred)**2).sum()/((o[:,j]-o[:,j].mean())**2).sum())
    print(cols, np.round(r2,2))

